#!/usr/bin/env python3
import json
import os
import re
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path

PLUGIN_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-plugin")
WORKSPACE_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-workspace")
SAFE_INGEST = PLUGIN_DIR / "scripts/safe_ingest.py"
REPO = "matthewmcneill/esp32-app-foundation"

brain_dir = Path.home() / ".gemini/antigravity/brain"
cutoff = datetime.now(timezone.utc).timestamp() - 86400
current_cid = "3e5a5219-f4f6-4923-8f36-9e644874e27b"

results = []

for conv_dir in sorted(brain_dir.iterdir()):
    if not conv_dir.is_dir() or conv_dir.name == current_cid:
        continue
    t_file = conv_dir / ".system_generated/logs/transcript.jsonl"
    if not t_file.exists():
        continue
    try:
        mtime = t_file.stat().st_mtime
    except OSError:
        continue
    if mtime < cutoff:
        continue

    # Read transcript line by line
    records = []
    try:
        with open(t_file, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if line:
                    try:
                        records.append(json.loads(line))
                    except json.JSONDecodeError:
                        pass
    except Exception as e:
        continue

    if not records:
        continue

    # Find initial user prompt
    user_prompt = ""
    for r in records:
        if r.get("type") == "USER_INPUT":
            user_prompt = r.get("content", "")
            break

    # Determine kind of conversation
    kind = "unknown"
    if "bug-fixer-engineering" in user_prompt or "Fix #" in user_prompt or "engineering_dispatcher" in user_prompt:
        kind = "engineering"
    elif "bug-fixer-triage" in user_prompt or "triage_dispatcher" in user_prompt or "Triage:" in user_prompt:
        kind = "triage"
    elif "bug-fixer-trajectory-review" in user_prompt or "trajectory_dispatcher" in user_prompt:
        kind = "trajectory"
    elif "architect" in user_prompt or "architect_dispatcher" in user_prompt:
        kind = "architect"
    else:
        # Check first record content or thinking
        text_dump = " ".join([r.get("content", "")[:200] for r in records[:5]])
        if "bug-fixer" in text_dump:
            kind = "bug-fixer-other"
        else:
            continue

    # Extract issue #
    issue_m = re.search(r"(?:Fix #|issue #|#)(\d+)", user_prompt)
    issue_num = int(issue_m.group(1)) if issue_m else None

    # Track tool calls and actions
    tool_calls = []
    test_runs = []
    pr_created = None
    git_commits = []
    files_edited = []
    errors = []
    final_response = ""

    for r in records:
        if r.get("type") == "PLANNER_RESPONSE":
            tc_list = r.get("tool_calls", [])
            for tc in tc_list:
                name = tc.get("name", "")
                args = tc.get("arguments", {})
                tool_calls.append(name)
                if name == "run_command":
                    cmd = args.get("CommandLine", "")
                    if "pio test" in cmd or "run_tests" in cmd or "test" in cmd:
                        test_runs.append(cmd)
                    if "git commit" in cmd:
                        git_commits.append(cmd)
                    if "gh pr create" in cmd:
                        pr_m = re.search(r"gh pr create.*", cmd)
                        if pr_m:
                            pr_created = cmd
                elif name in ("replace_file_content", "write_to_file"):
                    tf = args.get("TargetFile", "")
                    if tf:
                        files_edited.append(tf)
            if r.get("content"):
                final_response = r.get("content")

    # Look for PR URLs or numbers in final_response or tool call outputs
    pr_num = None
    if pr_created:
        prm = re.search(r"/pull/(\d+)", pr_created)
        if prm:
            pr_num = int(prm.group(1))
    if not pr_num:
        prm = re.search(r"/pull/(\d+)", final_response)
        if prm:
            pr_num = int(prm.group(1))

    # Look for status or exit messages
    exit_status = "completed"
    if "ENGINEERING_EXIT:" in final_response:
        exit_status = final_response[final_response.find("ENGINEERING_EXIT:"):].split("\n")[0]
    elif "TRIAGE_EXIT:" in final_response:
        exit_status = final_response[final_response.find("TRIAGE_EXIT:"):].split("\n")[0]
    elif "BLOCKED" in final_response:
        exit_status = "BLOCKED"

    results.append({
        "cid": conv_dir.name,
        "mtime": datetime.fromtimestamp(mtime, tz=timezone.utc).isoformat(),
        "kind": kind,
        "issue_num": issue_num,
        "tool_call_count": len(tool_calls),
        "test_runs_count": len(test_runs),
        "test_runs": test_runs[:5],
        "files_edited": list(set(files_edited)),
        "git_commits": len(git_commits),
        "pr_num": pr_num,
        "pr_created_cmd": bool(pr_created),
        "exit_status": exit_status,
        "final_snippet": final_response[:300].replace("\n", " ") if final_response else ""
    })

print(f"Parsed {len(results)} relevant conversations.")
with open(WORKSPACE_DIR / "tmp/conversations_summary.json", "w") as out_f:
    json.dump(results, out_f, indent=2)

print("Summary written to tmp/conversations_summary.json")

