#!/usr/bin/env python3
import json
import os
import re
import subprocess
import sys
from datetime import datetime, timezone, timedelta
from pathlib import Path

WORKSPACE_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-workspace")
PLUGIN_DIR = Path("/Users/mcneillm/Documents/Projects/esp32-app-foundation/.agents/plugins/bug-fixer-loop-plugin")
SAFE_INGEST = PLUGIN_DIR / "scripts/safe_ingest.py"
TMP_DIR = WORKSPACE_DIR / "tmp"
BRAIN_DIR = Path.home() / ".gemini/antigravity/brain"
CURRENT_CID = "3e5a5219-f4f6-4923-8f36-9e644874e27b"

cutoff_ts = datetime.now(timezone.utc).timestamp() - 86400
cutoff_iso = datetime.fromtimestamp(cutoff_ts, tz=timezone.utc).isoformat()

def run_cmd(cmd):
    return subprocess.run(cmd, capture_output=True, text=True)

# 1. Inspect Sidecar Logs
print("=== SIDECAR LOGS ===")
sidecar_base = Path.home() / ".gemini/antigravity/sidecar_data"
sidecar_logs = {}
if sidecar_base.exists():
    for sc in sidecar_base.iterdir():
        if sc.is_dir():
            slog = sc / "logs/sidecar.log"
            if slog.exists():
                lines = []
                with open(slog, "r", errors="replace") as f:
                    for l in f:
                        lines.append(l)
                recent_lines = [l for l in lines[-100:]] # last 100 lines
                sidecar_logs[sc.name] = recent_lines
                print(f"Sidecar {sc.name}: {len(lines)} total lines, {len(recent_lines)} sampled")

# 2. GitHub PRs and Issues via safe_ingest.py
print("\n=== GITHUB INGESTION ===")
# PRs
r_pr = run_cmd(["python3", str(SAFE_INGEST), "pr-list", "--state", "all", "--limit", "30"])
prs = []
if r_pr.returncode == 0:
    try:
        prs = json.loads(r_pr.stdout)
        print(f"Fetched {len(prs)} PRs successfully.")
    except Exception as e:
        print(f"Failed to parse PR JSON: {e}")
else:
    print(f"safe_ingest pr-list failed: {r_pr.stderr}")

# Open Issues
r_issues = run_cmd(["python3", str(SAFE_INGEST), "issue-list", "--state", "open", "--limit", "30"])
issues = []
if r_issues.returncode == 0:
    try:
        issues = json.loads(r_issues.stdout)
        print(f"Fetched {len(issues)} open issues successfully.")
    except Exception as e:
        print(f"Failed to parse issue JSON: {e}")
else:
    print(f"safe_ingest issue-list failed: {r_issues.stderr}")

# 3. Analyze Transcripts from last 24h
print("\n=== TRANSCRIPT ANALYSIS ===")
conv_analyses = []

for conv_dir in sorted(BRAIN_DIR.iterdir()):
    if not conv_dir.is_dir() or conv_dir.name == CURRENT_CID:
        continue
    t_file = conv_dir / ".system_generated/logs/transcript.jsonl"
    if not t_file.exists():
        continue
    try:
        if t_file.stat().st_mtime < cutoff_ts:
            continue
    except OSError:
        continue

    # Read records
    records = []
    try:
        with open(t_file, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if line:
                    try:
                        records.append(json.loads(line))
                    except json.JSONDecodeError:
                        pass
    except Exception:
        continue

    if not records:
        continue

    created_at = records[0].get("created_at")
    ended_at = records[-1].get("created_at")

    user_prompt = ""
    for r in records:
        if r.get("type") == "USER_INPUT":
            user_prompt = r.get("content", "")
            break

    # Determine kind
    if "bug-fixer-engineering" in user_prompt or "Fix #" in user_prompt or "engineering_dispatcher" in user_prompt:
        kind = "engineering"
    elif "bug-fixer-triage" in user_prompt or "triage_dispatcher" in user_prompt or "Triage:" in user_prompt:
        kind = "triage"
    elif "bug-fixer-trajectory-review" in user_prompt or "trajectory_dispatcher" in user_prompt:
        kind = "trajectory"
    elif "architect" in user_prompt or "architect_dispatcher" in user_prompt:
        kind = "architect"
    else:
        continue

    # Extract issue number
    issue_m = re.search(r"(?:Fix #|issue #|#)(\d+)", user_prompt)
    issue_num = int(issue_m.group(1)) if issue_m else None

    # Actions analysis
    tool_invocations = []
    test_results = []
    pr_created = None
    exit_statement = None
    errors = []

    for idx, r in enumerate(records):
        content = r.get("content", "")
        tc_list = r.get("tool_calls", [])

        # Tool execution details
        for tc in tc_list:
            name = tc.get("name", "")
            args = tc.get("arguments", {})
            tool_invocations.append(name)

            if name == "run_command":
                cmd = args.get("CommandLine", "")
                if "pio test" in cmd:
                    # check next step for output
                    pass
                if "gh pr create" in cmd:
                    pr_created = cmd

        # Check step results / tool responses for test output or errors
        if r.get("source") == "SYSTEM" or r.get("type") == "TOOL_OUTPUT":
            # Check for test summary
            if "SUMMARY" in content and "PASSED" in content:
                passed_m = re.search(r"(\d+) succeeded", content)
                failed_m = re.search(r"(\d+) failed", content)
                test_results.append({
                    "passed": int(passed_m.group(1)) if passed_m else 0,
                    "failed": int(failed_m.group(1)) if failed_m else 0,
                    "raw": content[:500]
                })
            elif "FAILED" in content and "test" in content:
                test_results.append({
                    "passed": 0,
                    "failed": 1,
                    "raw": content[:500]
                })

        if r.get("type") == "PLANNER_RESPONSE":
            if "ENGINEERING_EXIT:" in content:
                for line in content.split("\n"):
                    if "ENGINEERING_EXIT:" in line:
                        exit_statement = line.strip()
            elif "TRIAGE_EXIT:" in content:
                for line in content.split("\n"):
                    if "TRIAGE_EXIT:" in line:
                        exit_statement = line.strip()

    # If no explicit exit statement found, look at the last assistant message
    last_assistant_msg = ""
    for r in reversed(records):
        if r.get("type") == "PLANNER_RESPONSE" and r.get("content"):
            last_assistant_msg = r.get("content")
            break

    conv_analyses.append({
        "cid": conv_dir.name,
        "created_at": created_at,
        "ended_at": ended_at,
        "kind": kind,
        "issue_num": issue_num,
        "user_prompt_snippet": user_prompt[:200].replace("\n", " "),
        "total_steps": len(records),
        "tool_count": len(tool_invocations),
        "pr_created": pr_created is not None,
        "pr_created_cmd": pr_created,
        "test_results": test_results,
        "exit_statement": exit_statement,
        "last_assistant_msg_snippet": last_assistant_msg[:250].replace("\n", " ")
    })

print(f"Analyzed {len(conv_analyses)} conversations from last 24 hours.")

analysis_data = {
    "generated_at": datetime.now(timezone.utc).isoformat(),
    "cutoff": cutoff_iso,
    "sidecars": {k: len(v) for k, v in sidecar_logs.items()},
    "prs": prs,
    "issues": issues,
    "conversations": conv_analyses
}

with open(TMP_DIR / "full_analysis.json", "w") as f:
    json.dump(analysis_data, f, indent=2)

print("Saved to tmp/full_analysis.json")

