    else:
        if "architect" in user_prompt.lower():
            role = "architect"
        elif "triage" in user_prompt.lower():
            role = "triage"
        elif "engineering" in user_prompt.lower() or "fix #" in user_prompt.lower():
            role = "engineering"

    # Issue and PR numbers from user prompt
    issue_m = re.search(r"(?:Fix #|issue #|Issue #|#)(\d+)", user_prompt)
    issue_num = int(issue_m.group(1)) if issue_m else None

    pr_m = re.search(r"(?:PR #|pull/|PR:.*#)(\d+)", user_prompt)
    pr_num = int(pr_m.group(1)) if pr_m else None

    # Find tool actions & commands
    commands = []
    tests_run = []
    prs_created = []
    commits = []
    files_modified = set()

    for s in steps:
        for tc in s.get("tool_calls", []):
            tname = tc.get("name", "")
            targs = tc.get("arguments", {})
            if tname == "run_command":
                cmd = targs.get("CommandLine", "")
                commands.append(cmd)
                if "test" in cmd:
                    tests_run.append(cmd)
                if "git commit" in cmd:
                    commits.append(cmd)
                if "gh pr create" in cmd:
                    prs_created.append(cmd)
            elif tname == "call_mcp_tool":
                tool = targs.get("ToolName", "")
                if "test" in tool:
                    tests_run.append(f"mcp:{tool}")
            elif tname in ("replace_file_content", "write_to_file"):
                tf = targs.get("TargetFile", "")
                if tf:
                    files_modified.add(tf)

    # Extract test pass/fail results from content
    test_summary_matches = []
    for s in steps:
        content = s.get("content", "")
        if "SUMMARY" in content and ("succeeded" in content or "failed" in content or "PASSED" in content):
            test_summary_matches.append(content)
        elif "test cases:" in content:
            test_summary_matches.append(content)

    # Last assistant message
    last_msg = ""
    for s in reversed(steps):
        if s.get("type") == "PLANNER_RESPONSE" and s.get("content"):
            last_msg = s.get("content")
            break

    transcripts.append({
        "cid": conv_dir.name,
        "created_at": created_at,
        "ended_at": ended_at,
        "role": role,
        "issue_num": issue_num,
        "pr_num": pr_num,
        "user_prompt_snippet": user_prompt[:150].replace("\n", " "),
        "total_steps": len(steps),
        "commands_count": len(commands),
        "tests_run": tests_run,
        "commits_count": len(commits),
        "prs_created": prs_created,
        "files_modified_count": len(files_modified),
        "test_summaries_count": len(test_summary_matches),
        "last_msg_snippet": last_msg[:300].replace("\n", " ")
    })

print(f"Detailed history extracted for {len(transcripts)} conversations.")

# Group by role
by_role = defaultdict(list)
for t in transcripts:
    by_role[t["role"]].append(t)

print("\n=== ROLE BREAKDOWN ===")
for r, tlist in sorted(by_role.items()):
    print(f"{r}: {len(tlist)} sessions")

print("\n=== SESSIONS TIMELINE (CHRONOLOGICAL) ===")
transcripts.sort(key=lambda x: x["created_at"] or "")
for t in transcripts:
    issue_info = f"Issue #{t['issue_num']}" if t['issue_num'] else "No Issue"
    pr_info = f"PR #{t['pr_num']}" if t['pr_num'] else ""
    tests = f"{len(t['tests_run'])} tests" if t['tests_run'] else "no tests"
    prs = f"PR CREATED" if t['prs_created'] else ""
    print(f"[{t['created_at'][:19]}] {t['role']:<18} | {issue_info:<11} | {pr_info:<8} | {tests:<10} | {prs:<10} | CID {t['cid'][:8]}")
    if t['last_msg_snippet']:
        print(f"   > Summary: {t['last_msg_snippet'][:120]}")

